import{_ as t,o as a,c as r,a0 as s}from"./chunks/framework.BQGW-Zpy.js";const m=JSON.parse('{"title":"Problem Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/problem-analysis.md","filePath":"get-started/problem-analysis.md"}'),o={name:"get-started/problem-analysis.md"};function n(i,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="problem-analysis" tabindex="-1">Problem Analysis <a class="header-anchor" href="#problem-analysis" aria-label="Permalink to &quot;Problem Analysis&quot;">​</a></h1><h3 id="_2-1-what-actually-makes-cross-border-expensive" tabindex="-1">2.1 What actually makes cross-border expensive <a class="header-anchor" href="#_2-1-what-actually-makes-cross-border-expensive" aria-label="Permalink to &quot;2.1 What actually makes cross-border expensive&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Cause</th><th>Effect</th></tr></thead><tbody><tr><td>Correspondent banking chains</td><td>Each hop adds a fee, a delay and an FX spread</td></tr><tr><td>Pre-funding (nostro/vostro)</td><td>Capital sits idle in every destination country; the cost is passed on</td></tr><tr><td>Batch settlement windows</td><td>Cut-off times, weekends, T+1/T+2</td></tr><tr><td>Fragmented compliance</td><td>Each institution repeats KYC; none can verify the other&#39;s</td></tr><tr><td>Opaque FX</td><td>The spread, not the stated fee, is where the cost hides</td></tr></tbody></table><h3 id="_2-2-the-compliance-gap-the-one-we-address" tabindex="-1">2.2 The compliance gap, the one we address <a class="header-anchor" href="#_2-2-the-compliance-gap-the-one-we-address" aria-label="Permalink to &quot;2.2 The compliance gap, the one we address&quot;">​</a></h3><p>Every regulated party in a cross-border chain runs its own checks. But when a regulator or counterparty later asks <em>&quot;was this transaction compliant at the time it happened?&quot;</em>, the evidence is a database row inside one institution, mutable, and attested by nobody but its owner.</p><p><strong>Formal problem statement:</strong></p><blockquote><p>In a cross-border payment routed through multiple independently licensed institutions, no party can independently verify that another party&#39;s compliance checks were performed at the time of the transaction, and every party&#39;s record of that fact is unilaterally revisable.</p></blockquote><h3 id="_2-3-what-we-are-explicitly-not-solving" tabindex="-1">2.3 What we are explicitly <em>not</em> solving <a class="header-anchor" href="#_2-3-what-we-are-explicitly-not-solving" aria-label="Permalink to &quot;2.3 What we are explicitly *not* solving&quot;">​</a></h3><p>Stated here rather than discovered by an examiner:</p><ul><li><strong>We do not open new corridors.</strong> Coverage is a licensing and partner problem, not a technical one (<a href="./../legal/why-this-is-legal.html">this section</a>).</li><li><strong>We do not eliminate capital lock-up.</strong> We relocate it (<a href="./../business/business-model.html">this section</a>).</li><li><strong>We do not remove the need for KYC.</strong> We make its result provable (<a href="./../legal/why-this-is-legal.html">this section</a>).</li></ul><hr>',11)])])}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
